const assert = require('node:assert/strict');
const { readFile, readdir } = require('node:fs/promises');
const path = require('node:path');
const { describe, it } = require('node:test');

const projectRoot = path.resolve(__dirname, '..');
const tauriDirectory = path.join(projectRoot, 'src-tauri');
const capabilityDirectory = path.join(tauriDirectory, 'capabilities');
const permissionDirectory = path.join(
  tauriDirectory,
  'permissions',
  'autogenerated',
);

const companionCommandPermissions = [
  'allow-ask-ai',
  'allow-activate-reminder-events',
  'allow-activate-pomodoro-events',
  'allow-start-pomodoro',
  'allow-custom-pomodoro-panel-closed',
  'allow-create-reminder',
  'allow-update-reminder',
  'allow-delete-reminder',
  'allow-get-reminder',
  'allow-list-reminders',
  'allow-mark-reminder-completed',
  'allow-get-cursor-position',
  'allow-get-daily-planner',
  'allow-get-runtime-settings',
  'allow-get-companion-window-position',
  'allow-move-companion-window',
  'allow-set-companion-content-height',
  'allow-show-companion-context-menu',
  'allow-stream-cursor-positions',
  'allow-stop-cursor-positions',
  'allow-update-user-name',
  'allow-update-sticky-message',
];
const preferencesCommandPermissions = [
  'allow-update-ai-configuration',
  'allow-list-ai-models',
  'allow-test-ai-connection',
  'allow-get-preferences-settings',
  'allow-update-preferences-settings',
  'allow-get-credential-status',
  'allow-save-credential',
  'allow-delete-credential',
  'allow-get-update-status',
  'allow-check-for-updates',
];
const registeredCommandPermissions = [
  ...companionCommandPermissions,
  ...preferencesCommandPermissions,
];
const eventPermissions = [
  'core:event:allow-listen',
  'core:event:allow-unlisten',
];
const aiCommandPermissions = [
  'allow-ask-ai',
  'allow-update-ai-configuration',
  'allow-list-ai-models',
  'allow-test-ai-connection',
];
const updaterCommandPermissions = [
  'allow-get-update-status',
  'allow-check-for-updates',
];

const readJson = async (target) =>
  JSON.parse(await readFile(target, 'utf8'));

const readCapability = (role) =>
  readJson(path.join(capabilityDirectory, `${role}.json`));

describe('Tauri IPC authorization', () => {
  it('loads only the two exact local renderer capabilities', async () => {
    const configuration = await readJson(
      path.join(tauriDirectory, 'tauri.conf.json'),
    );
    const capabilityFiles = (await readdir(capabilityDirectory))
      .filter((entry) => entry.endsWith('.json'))
      .sort();

    assert.deepEqual(capabilityFiles, [
      'companion.json',
      'preferences.json',
    ]);
    assert.deepEqual(
      [...configuration.app.security.capabilities].sort(),
      ['companion', 'preferences'],
    );

    for (const role of ['companion', 'preferences']) {
      const capability = await readCapability(role);

      assert.equal(capability.local, true);
      assert.equal(Object.hasOwn(capability, 'remote'), false);
      assert.equal(Object.hasOwn(capability, 'windows'), false);
      assert.deepEqual(capability.webviews, [role]);
      assert.equal(
        capability.webviews.some((label) => label.includes('*')),
        false,
      );
    }
  });

  it('keeps production updater trust and feed configuration deferred to Phase 11', async () => {
    const configuration = await readJson(
      path.join(tauriDirectory, 'tauri.conf.json'),
    );

    assert.deepEqual(configuration.plugins?.updater, {
      pubkey: '',
      endpoints: [],
    });
    assert.notEqual(configuration.bundle?.createUpdaterArtifacts, true);
  });

  it('grants completed commands only to their exact renderer role', async () => {
    const companion = await readCapability('companion');
    const preferences = await readCapability('preferences');

    assert.deepEqual(companion.permissions, [
      ...companionCommandPermissions,
      ...eventPermissions,
    ]);
    assert.deepEqual(preferences.permissions, [
      ...preferencesCommandPermissions,
      ...eventPermissions,
    ]);

    for (const permission of companionCommandPermissions) {
      assert.equal(companion.permissions.includes(permission), true);
      assert.equal(preferences.permissions.includes(permission), false);
    }
    for (const permission of preferencesCommandPermissions) {
      assert.equal(preferences.permissions.includes(permission), true);
      assert.equal(companion.permissions.includes(permission), false);
    }
  });

  it('does not grant broad, remote, or renderer-side mutation authority', async () => {
    const forbiddenPermissions = new Set([
      'core:default',
      'core:event:default',
      'core:event:allow-emit',
      'core:event:allow-emit-to',
    ]);
    const forbiddenPrefixes = [
      'fs:',
      'http:',
      'shell:',
      'process:',
      'clipboard:',
      'global-shortcut:',
      'menu:',
      'notification:',
      'tray:',
      'updater:',
    ];

    for (const role of ['companion', 'preferences']) {
      const capability = await readCapability(role);

      for (const permission of capability.permissions) {
        assert.equal(permission.includes('*'), false);
        assert.equal(forbiddenPermissions.has(permission), false);
        assert.equal(
          forbiddenPrefixes.some((prefix) =>
            permission.startsWith(prefix),
          ),
          false,
        );
      }
    }
  });

  it('exposes only status and check to Preferences', async () => {
    const companion = await readCapability('companion');
    const preferences = await readCapability('preferences');
    const grantedUpdaterPermissions = [
      ...companion.permissions,
      ...preferences.permissions,
    ].filter((permission) =>
      updaterCommandPermissions.includes(permission),
    );
    const tauriCommands = await readFile(
      path.join(projectRoot, 'src', 'desktop', 'tauriCommands.ts'),
      'utf8',
    );

    assert.deepEqual(
      grantedUpdaterPermissions,
      updaterCommandPermissions,
    );
    assert.equal(
      companion.permissions.some((permission) =>
        updaterCommandPermissions.includes(permission),
      ),
      false,
    );
    assert.deepEqual(
      preferences.permissions.filter((permission) =>
        updaterCommandPermissions.includes(permission),
      ),
      updaterCommandPermissions,
    );
    assert.doesNotMatch(
      tauriCommands,
      /download[_A-Z-]?update|install[_A-Z-]?update|restart[_A-Z-]?update/i,
    );
  });

  it('generates one narrow allow/deny permission pair per command', async () => {
    const permissionFiles = (await readdir(permissionDirectory))
      .filter((entry) => entry.endsWith('.toml'))
      .sort();

    assert.deepEqual(
      permissionFiles,
      registeredCommandPermissions
        .map(
          (permission) =>
            `${permission.slice('allow-'.length).replaceAll('-', '_')}.toml`,
        )
        .sort(),
    );

    for (const permission of registeredCommandPermissions) {
      const commandName = permission
        .slice('allow-'.length)
        .replaceAll('-', '_');
      const contents = await readFile(
        path.join(permissionDirectory, `${commandName}.toml`),
        'utf8',
      );

      assert.match(contents, new RegExp(`identifier = "${permission}"`));
      assert.match(
        contents,
        new RegExp(
          `identifier = "deny-${permission.slice('allow-'.length)}"`,
        ),
      );
      assert.match(
        contents,
        new RegExp(`commands.allow = \\["${commandName}"\\]`),
      );
      assert.match(
        contents,
        new RegExp(`commands.deny = \\["${commandName}"\\]`),
      );
    }
  });

  it('exposes only the exact final-response AI command surface', async () => {
    const companion = await readCapability('companion');
    const preferences = await readCapability('preferences');
    const grantedAiPermissions = [
      ...companion.permissions,
      ...preferences.permissions,
    ].filter((permission) =>
      aiCommandPermissions.includes(permission),
    );
    const tauriCommands = await readFile(
      path.join(projectRoot, 'src', 'desktop', 'tauriCommands.ts'),
      'utf8',
    );

    assert.deepEqual(grantedAiPermissions, aiCommandPermissions);
    assert.equal(
      companion.permissions.includes('allow-ask-ai'),
      true,
    );
    assert.deepEqual(
      preferences.permissions.filter((permission) =>
        aiCommandPermissions.includes(permission),
      ),
      aiCommandPermissions.slice(1),
    );
    assert.match(tauriCommands, /askAI: 'ask_ai'/);
    assert.match(
      tauriCommands,
      /updateAiConfiguration: 'update_ai_configuration'/,
    );
    assert.match(tauriCommands, /listAIModels: 'list_ai_models'/);
    assert.match(
      tauriCommands,
      /testAIConnection: 'test_ai_connection'/,
    );
    assert.doesNotMatch(
      tauriCommands,
      /stream[_A-Z-]?ai|cancel[_A-Z-]?ai|provider[_A-Z-]?health|latency/i,
    );
  });
});
